<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= htmlspecialchars($d['name'] ?? 'Portfolio') ?> | Data Story</title><link href="https://fonts.googleapis.com/css2?family=DM+Mono&family=Manrope:wght@400;600;700;800&display=swap" rel="stylesheet"><style>:root{--mint:#8dfbd0;--blue:#6ea9ff;--ink:#0c1018;--panel:#151b28;--line:#293347}*{box-sizing:border-box}body{margin:0;background:var(--ink);color:#eff5ff;font-family:Manrope,Arial}.shell{max-width:1240px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;padding:12px 0 48px;color:#a6b0c2;font:12px 'DM Mono',monospace;text-transform:uppercase}.hero{display:grid;grid-template-columns:1.2fr .8fr;gap:18px}.intro,.score,.metric,.project,.timeline{background:var(--panel);border:1px solid var(--line);border-radius:20px}.intro{padding:54px}.kicker{color:var(--mint);font:12px 'DM Mono',monospace;text-transform:uppercase;letter-spacing:.14em}.intro h1{font-size:clamp(48px,8vw,104px);line-height:.88;letter-spacing:-.08em;margin:22px 0}.intro p{max-width:580px;color:#b8c2d3;font-size:18px;line-height:1.6}.score{padding:30px;display:flex;flex-direction:column;justify-content:space-between;background:linear-gradient(145deg,#17233a,#10151f)}.ring{width:180px;height:180px;border-radius:50%;display:grid;place-items:center;background:conic-gradient(var(--mint) <?= min(100, max(0, (int)($d['score'] ?? 82))) ?>%,#293347 0);margin:auto}.ring i{font-style:normal;background:var(--panel);width:145px;height:145px;border-radius:50%;display:grid;place-items:center;font-size:38px;font-weight:800}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin:18px 0}.metric{padding:23px}.metric strong{display:block;font-size:34px;color:var(--blue);margin:8px 0}.metric span{font:12px 'DM Mono',monospace;color:#a6b0c2;text-transform:uppercase}.section{margin-top:70px}.section h2{font-size:27px;margin:0 0 20px}.projects{display:grid;grid-template-columns:repeat(12,1fr);gap:18px}.project{grid-column:span 5;padding:26px;min-height:210px}.project:nth-child(3n+2){grid-column:span 7;background:linear-gradient(135deg,#1e3255,#15233b)}.project h3{font-size:25px;margin:35px 0 8px}.project p,.timeline p{color:#aeb9ca;line-height:1.5}.timeline{padding:8px 24px}.row{display:grid;grid-template-columns:160px 1fr;gap:20px;padding:20px 0;border-bottom:1px solid var(--line)}.row:last-child{border:0}.tags{display:flex;gap:9px;flex-wrap:wrap}.tag{padding:9px 12px;border:1px solid var(--line);border-radius:99px;color:var(--mint);font:12px 'DM Mono',monospace}@media(max-width:700px){.hero,.grid{grid-template-columns:1fr}.projects{display:block}.project{margin-bottom:15px}.row{grid-template-columns:1fr}.intro{padding:32px}}</style></head><body><main class="shell"><nav class="top"><span>Data Story / Results dashboard</span><span><?= htmlspecialchars($d['name'] ?? 'Portfolio') ?></span></nav><section class="hero"><article class="intro"><span class="kicker">Evidence-led portfolio</span><h1><?= htmlspecialchars($d['name'] ?? 'Portfolio Owner') ?></h1><p><?= htmlspecialchars($d['bio'] ?? 'A clear account of the work, choices, and measurable outcomes behind every project.') ?></p></article><aside class="score"><span class="kicker">Portfolio signal</span><div class="ring"><i><?= htmlspecialchars((string)($d['score'] ?? 82)) ?></i></div><span>Craft, clarity and readiness score</span></aside></section><section class="grid"><div class="metric"><span>Selected work</span><strong><?= count($projects) ?></strong>Case studies</div><div class="metric"><span>Capabilities</span><strong><?= count($skills) ?></strong>Core skills</div><div class="metric"><span>Career moves</span><strong><?= count($experience) ?></strong>Timeline entries</div></section><section class="section"><h2>Project signals</h2><div class="projects"><?php foreach($projects ?: [['title'=>'Your next outcome','description'=>'Add project detail in the editor.']] as $p):